import { API_OPT } from '../Utils/constants'

const VideoBg = ({movieId}) => {
    const getMovieVideo=async()=>{
        const data=await fetch('https://api.themoviedb.org/3/movie/1241982/videos?language=en-US',API_OPT);
        const json= await data.json();
        // console.log(json)
        const filterTrailer=json.results.filter((v)=>v.type=="Trailer")
       const trailer=filterTrailer.length?filterTrailer[0]:json.results[0];
    }
    useEffect(()=>{
   getMovieVideo()
    },[])
  return (
    <div>
      <iframe width="560" height="315" src="https://www.youtube.com/embed/jRXKbpF9kZM?si=oSPYtEebj_A8p_JB" title="YouTube video player" frameBorder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerPolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>
    </div>
  )
}

export default VideoBg
